// Block (composition) — a labeled collection of partner logos.
// Grid owns responsive logo arrangement; Stack owns section spacing and this Block owns the label structure.
import { useId } from "react";
import type { ReactNode, Ref } from "react";
import { Grid } from "../layouts/Grid";
import type { Responsive } from "../layouts/responsive";
import { Stack } from "../layouts/Stack";
import "./LogoCloud.css";

export interface LogoCloudProps {
  /** Each mark as a bare `<img src alt>` or `<svg viewBox>`, with no size: the Block owns the box
   *  and the mark is contained inside it (`prop-usage-contract.md` § Ratio). */
  logos: ReactNode[];
  /** The one box every mark shares: `wordmark` is 5 by 1, `symbol` is square. */
  markShape?: "wordmark" | "symbol";
  columns?: Responsive<number>;
  label?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function LogoCloud({
  logos,
  markShape = "wordmark",
  columns = { small: 2, medium: 5 },
  label,
  className,
  ref,
}: LogoCloudProps) {
  const labelId = useId();

  return (
    <Stack
      as="section"
      ref={ref}
      gap="large"
      aria-label={label ? undefined : "Partner logos"}
      aria-labelledby={label ? labelId : undefined}
      className={className ? `sd-logocloud ${className}` : "sd-logocloud"}
    >
      {/* One rung below the wordmarks it introduces — CONTRASTIVE, and the two are read together
          (`naming-convention.md` § The size axis defaults to `medium`). Without it the eyebrow and
          the logos are the same size and weight, with nothing to separate them. */}
      {label && (
        <h2 id={labelId} className="sd-logocloud__label sd-type-label-small">
          {label}
        </h2>
      )}
      <Grid columns={columns} gap="large" align="center">
        {logos.map((logo, index) => (
          <div key={index} className="sd-logocloud__item" data-mark-shape={markShape}>
            {logo}
          </div>
        ))}
      </Grid>
    </Stack>
  );
}

.sd-logocloud {
  width: 100%;
}

.sd-logocloud__label {
  margin: 0;
  text-align: center;
}

/* One box per mark (prop-usage-contract.md § Ratio): the box's HEIGHT is a Sys rung and its width
   follows from the ratio, so marks of any drawn proportion read as one even row. Not the track
   width: a square symbol sized by a 2-up track at 390 would stand ~170px tall. `max-inline-size`
   keeps a wordmark box inside a narrow track. `justify-self`, because a stretched grid item would
   take the track's width and drop the ratio. */
.sd-logocloud__item {
  display: flex;
  align-items: center;
  justify-content: center;
  justify-self: center;
  block-size: var(--sd-control-height-x-small);
  aspect-ratio: 5;
  max-inline-size: 100%;
  min-width: 0;
}

.sd-logocloud__item[data-mark-shape="symbol"] {
  aspect-ratio: 1;
}

@media (min-width: 768px) {
  .sd-logocloud__item {
    block-size: var(--sd-control-height-small);
  }
}

/* The mark fills the box and is contained in it, so the consumer passes no size. A direct child
   only, the same reach as `.sd-list-box__item > [slot]`: the Block cannot class markup it does not
   render. */
.sd-logocloud__item > img,
.sd-logocloud__item > svg {
  inline-size: 100%;
  block-size: 100%;
  object-fit: contain;
}
